@Composable private fun BoxV2Grid(entries:List<GameDexService.GameDexEntry>,captured:Set<Int>,onPokemonClick:(GameDexService.GameDexEntry)->Unit){Column(Modifier.fillMaxSize(),verticalArrangement=Arrangement.spacedBy(4.dp)){repeat(5){row->Row(Modifier.weight(1f).fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(4.dp)){repeat(6){col->val i=row*6+col;Box(Modifier.weight(1f).fillMaxHeight()){entries.getOrNull(i)?.let{p->BoxV2Slot(p,p.nationalId in captured){onPokemonClick(p)}}?:Surface(Modifier.fillMaxSize(),shape=RoundedCornerShape(11.dp),color=BoxSurface.copy(alpha=.45f)){} }}}}}}
