@Composable private fun BoxV2Search(d:List<GameDexService.GameDexEntry>,c:Set<Int>,dismiss:()->Unit,select:(GameDexService.GameDexEntry)->Unit,open:(GameDexService.GameDexEntry)->Unit){var q by remember{mutableStateOf("")};val x=q.trim().removePrefix("#");val r=remember(d,q){if(x.isBlank())emptyList()else d.filter{it.name.contains(x,true)||it.gameNumber.toString()==x||it.nationalId.toString()==x}.take(12)};AlertDialog(dismiss,{Text("Pesquisar Pokémon")},{Column{OutlinedTextField(q,{q=it},Modifier.fillMaxWidth(),singleLine=true,leadingIcon={Icon(Icons.Default.Search,null)},placeholder={Text("Nome ou número")});LazyColumn(Modifier.heightIn(max=360.dp)){items(r,key={it.nationalId}){p->Row(Modifier.fillMaxWidth().clickable{select(p)}.padding(7.dp),verticalAlignment=Alignment.CenterVertically){AsyncImage(p.spriteUrl,p.name,Modifier.size(48.dp));Column(Modifier.weight(1f)){Text(formatPokemonName(p.name),fontWeight=FontWeight.SemiBold);Text("#${p.gameNumber.toString().padStart(3,'0')} · ${if(p.nationalId in c)"Capturado" else "Faltando"}")};TextButton({open(p)}){Text("Ficha")}}}}}}, {},{TextButton(dismiss){Text("Fechar")}})}